int FS_LoadFile(char *path, void **buffer)
{
	fileHandle_t f;
	const int size = FS_FOpenFile(path, &f, FS_READ);

	if (size <= 0)
	{
		if (buffer)
			*buffer = NULL;

		return size;
	}

	if (!buffer)
	{
		FS_FCloseFile(f);
		return size;
	}

	byte *buf = Z_Malloc(size);
	*buffer = buf;

	FS_Read(buf, size, f);
	FS_FCloseFile(f);

	return size;
}

