			// Skip packs using pakX naming scheme...
			for (int j = 0; j < 100; j++)
			{
				char buf[16];
				Com_sprintf(buf, sizeof(buf), "/pak%i.%s", j, ext);

				if (strstr(filenames[i], buf))
				{
					numberedpak = true;
					break;
				}
			}

			if (numberedpak)
				continue;

			if (strrchr(filenames[i], '/'))
			{
				if (ispak)
